/* ShaderScene: the canvas, filling its positioned ancestor.
   Placement and clipping belong to that ancestor, as with ShaderField: where
   a scene sits is a layout decision. The ground under the canvas is the
   page's, so a machine that cannot run WebGL2 shows the plain page. */

.ds-shader-scene {
  position: absolute;
  inset: 0;
  overflow: hidden;
  /* Scenery, never a target. */
  pointer-events: none;
  background-color: var(--color-bg-page-primary);
}

.ds-shader-scene__canvas {
  display: block;
  width: 100%;
  height: 100%;
}

'use client';

import React from 'react';
import { MOTION_RENDERER_WATCHDOG_MS } from '../../tokens/motion';
import { PASSES } from './passes';
import { coloursFor, createRenderer } from './renderer';
import { SCENES } from './scenes';
import { defaultsFor, type Values } from './types';
import './ShaderScene.css';

/** The scenes ShaderScene paints. */
export type ShaderSceneId = 'horizon' | 'rift';

/**
 * How the scene resolved, the same three states ShaderField reports.
 * `pending` while the GL context comes up (bounded by a watchdog), `active`
 * once a frame has painted, `unavailable` when it is disabled or WebGL2
 * cannot run it.
 */
export type ShaderSceneStatus = 'pending' | 'active' | 'unavailable';

/** One finishing pass's setting: whether it runs, and its own settings. */
export type ShaderScenePassSetting = {
  /** Run the pass. Each pass has its own default. */
  on?: boolean;
  /** The pass's settings, merged over its defaults. */
  params?: Partial<Record<string, number>>;
};

/** Props owned by ShaderScene itself; everything else falls through to the root. */
type ShaderSceneOwnProps = {
  /** The scene to paint: `horizon`, a planet's limb at night, or `rift`, a glowing tear. */
  scene?: ShaderSceneId;
  /**
   * The scene's settings, merged over its defaults (`SHADER_SCENES` lists each
   * scene's keys and ranges), so passing one changes one thing. Changing them
   * never rebuilds the GL state.
   */
  params?: Partial<Record<string, number>>;
  /**
   * The finishing passes (`scrim`, `vignette`, `fadeTop`, `fadeBottom`,
   * `grain`), each merged over its defaults.
   */
  passes?: Partial<Record<string, ShaderScenePassSetting>>;
  /** Scene seconds per second: how fast it moves. 0 holds it still. */
  speed?: number;
  /**
   * A ref the scene reads every frame in place of `params`, `passes` and
   * `speed`, for a host that tunes it by drag: writing the ref moves the
   * scene and renders nothing. Empty falls back to the props.
   */
  liveRef?: React.RefObject<Values | null>;
  /**
   * False never starts WebGL and reports `unavailable`, leaving the page
   * ground: the kill switch, as on ShaderField.
   */
  enabled?: boolean;
  /**
   * Called whenever the status changes. Drive a fallback from this: the scene
   * paints only the page ground when it cannot run, and what to show instead
   * is the caller's design decision.
   */
  onStatusChange?: (status: ShaderSceneStatus) => void;
  /** Additional CSS classes */
  className?: string;
};

export interface ShaderSceneProps
  extends ShaderSceneOwnProps,
    Omit<React.ComponentPropsWithRef<'div'>, keyof ShaderSceneOwnProps> {}

const DEFAULT_SPEED = 1.6;

/**
 * ShaderScene paints one of the system's shader scenes, a horizon or a rift,
 * in WebGL2, with finishing passes over it (a scrim, a vignette, top and
 * bottom fades to the page, film grain). Its colours are the background
 * field's roles (`--color-ambient-*`) read from the live cascade at the
 * scene, so it re-themes with `data-theme`, a preset or any scoped override,
 * and its fades melt into the page ground.
 *
 * Both scenes are night scenes: they add light over a dark ground. On a light
 * page each computes its light against a dark ground of its own and lays it
 * onto the page as a pale tint, so it reads as a soft dawn rather than a dark
 * block. Nothing here sets `data-theme`, which would hide a preset's colours.
 *
 * It is scenery, not interface. It fills its positioned ancestor and is inert
 * to pointer events and to assistive tech; give the ancestor the placement and
 * the clipping. It honours reduced motion in JavaScript, holding a still frame
 * that still answers its settings, and paints the page ground alone where
 * WebGL2 is unavailable.
 */
export function ShaderScene({
  scene = 'horizon',
  params,
  passes,
  speed = DEFAULT_SPEED,
  liveRef,
  enabled = true,
  onStatusChange,
  className = '',
  ref,
  ...rest
}: ShaderSceneProps) {
  const hostRef = React.useRef<HTMLDivElement | null>(null);
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);
  const definition = SCENES.find((s) => s.id === scene) ?? SCENES[0];

  /* The props merged over the defaults, kept in a ref the frame loop reads,
     so a new prop moves the scene without rebuilding the program. */
  const merged = React.useMemo<Values>(
    () => ({
      speed,
      scene: { ...defaultsFor(definition.params), ...params } as Record<string, number>,
      passes: Object.fromEntries(
        PASSES.map((pass) => {
          const setting = passes?.[pass.id];
          return [
            pass.id,
            {
              on: setting?.on ?? pass.on,
              params: { ...defaultsFor(pass.params), ...setting?.params } as Record<string, number>,
            },
          ];
        })
      ),
    }),
    [definition, params, passes, speed]
  );
  const mergedRef = React.useRef(merged);
  React.useEffect(() => {
    mergedRef.current = merged;
  }, [merged]);

  /* 'failed' and 'painted' come from the GL effect; the watchdog bounds a
     context that never paints, so pending can never be terminal. */
  const [gl, setGl] = React.useState<'pending' | 'failed' | 'painted'>('pending');
  const [gaveUp, setGaveUp] = React.useState(false);
  React.useEffect(() => {
    if (!enabled || gl !== 'pending') return;
    const timer = window.setTimeout(() => setGaveUp(true), MOTION_RENDERER_WATCHDOG_MS);
    return () => window.clearTimeout(timer);
  }, [enabled, gl]);
  const status: ShaderSceneStatus =
    !enabled || gl === 'failed'
      ? 'unavailable'
      : gl === 'painted'
        ? 'active'
        : gaveUp
          ? 'unavailable'
          : 'pending';
  const notify = React.useRef(onStatusChange);
  React.useEffect(() => {
    notify.current = onStatusChange;
  }, [onStatusChange]);
  React.useEffect(() => {
    notify.current?.(status);
  }, [status]);

  const setRef = (node: HTMLDivElement | null) => {
    hostRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };

  React.useEffect(() => {
    if (!enabled) return;
    const host = hostRef.current;
    const canvas = canvasRef.current;
    const context = canvas?.getContext('webgl2', { antialias: false, alpha: false });
    const renderer = context ? createRenderer(context, definition, PASSES) : null;
    if (!host || !canvas || !renderer) {
      /* Reported from a frame, not the effect body, so the effect never
         sets state synchronously. */
      const failed = requestAnimationFrame(() => setGl('failed'));
      return () => cancelAnimationFrame(failed);
    }

    const applyColours = () => renderer.setColours(coloursFor(host, definition));
    const resize = () => {
      const ratio = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(host.clientWidth * ratio));
      canvas.height = Math.max(1, Math.round(host.clientHeight * ratio));
    };

    const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let time = 20;
    let last = performance.now();
    let frame = 0;
    let painted = false;
    const draw = (now: number) => {
      const values = liveRef?.current ?? mergedRef.current;
      const dt = Math.min(0.1, (now - last) / 1000);
      last = now;
      if (!still) time += dt * values.speed;
      renderer.draw(values, time, canvas.width, canvas.height);
      if (!painted) {
        painted = true;
        setGl('painted');
      }
      frame = requestAnimationFrame(draw);
    };
    /* The loop runs only near the screen, as ShaderField's does: it stops
       when the scene scrolls away and starts again 200px before it returns,
       so a page of stages draws only the ones in view. A hidden tab stops
       requestAnimationFrame by itself. */
    const start = () => {
      if (frame) return;
      last = performance.now();
      frame = requestAnimationFrame(draw);
    };
    const stop = () => {
      cancelAnimationFrame(frame);
      frame = 0;
    };

    applyColours();
    resize();
    start();
    const visibilityObserver =
      typeof IntersectionObserver === 'undefined'
        ? null
        : new IntersectionObserver(
            (entries) => (entries[entries.length - 1].isIntersecting ? start() : stop()),
            { rootMargin: '200px 0px' }
          );
    visibilityObserver?.observe(host);

    const sizeObserver = new ResizeObserver(resize);
    sizeObserver.observe(host);
    /* A theme flip, a preset and a live override (an inline custom property
       on the root) all re-read the colours. */
    const themeObserver = new MutationObserver(applyColours);
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['data-theme', 'data-brand', 'style'],
    });

    return () => {
      stop();
      visibilityObserver?.disconnect();
      sizeObserver.disconnect();
      themeObserver.disconnect();
      renderer.dispose();
    };
  }, [definition, liveRef, enabled]);

  const classes = ['ds-shader-scene', className].filter(Boolean).join(' ');

  return (
    <div {...rest} ref={setRef} className={classes} data-status={status} aria-hidden="true">
      {enabled && <canvas ref={canvasRef} className="ds-shader-scene__canvas" />}
    </div>
  );
}

/* The engine's data and helpers, re-exported below the component so the
   docs parser names the component after itself (see ShaderField.tsx), and
   so the barrel carries what a host needs to draw controls for a scene. */
export type {
  ParamSpec as ShaderSceneParamSpec,
  Scene as ShaderSceneDefinition,
  Pass as ShaderScenePass,
  Values as ShaderSceneValues,
  Recipe as ShaderSceneRecipe,
} from './types';
/* eslint-disable react-refresh/only-export-components */
export { SCENES as SHADER_SCENES } from './scenes';
export { PASSES as SHADER_PASSES } from './passes';
export { defaultsFor as shaderSceneDefaults } from './types';
export { bakeThumbnails as shaderSceneStills } from './renderer';
/* eslint-enable react-refresh/only-export-components */

/**
 * Builds one fragment shader from a scene and the passes: the uniforms
 * both declare, the common GLSL, the scene's `scene()`, each pass's
 * function, and a `main` that runs the scene, lays a night scene onto a
 * light page when it must (u_lightMode), then runs the light passes, the
 * encode and the srgb passes, each gated by its `u_<id>_on`.
 */
import { COMMON_GLSL } from "./common.glsl";
import type { Pass, Scene } from "./types";
import { MAX_COLOURS } from "./types";

export const VERTEX = /* glsl */ `#version 300 es
void main() {
  vec2 p = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}
`;

/** Every float uniform the shader declares, for the canvas to set each frame. */
export function uniformNames(scene: Scene, passes: Pass[]) {
  return [
    ...scene.params.map((param) => `u_${param.key}`),
    ...passes.flatMap((pass) => [
      `u_${pass.id}_on`,
      ...pass.params.map((param) => `u_${pass.id}_${param.key}`),
    ]),
  ];
}

export function assemble(scene: Scene, passes: Pass[]) {
  const floats = uniformNames(scene, passes)
    .map((name) => `uniform float ${name};`)
    .join("\n");
  const call = (stage: Pass["stage"], target: string) =>
    passes
      .filter((pass) => pass.stage === stage)
      .map((pass) => `  if (u_${pass.id}_on > 0.5) ${target} = pass_${pass.id}(${target}, uv);`)
      .join("\n");

  return /* glsl */ `#version 300 es
precision highp float;

uniform vec2 u_size;
uniform float u_time;
uniform vec3 u_ground;   // the scene's ground: the page's, or a night scene's own
uniform vec3 u_page;     // the page's ground, which the passes fade to
uniform float u_lightMode; // 1: a night scene laid onto a light page
uniform vec3 u_col[${MAX_COLOURS}];
${floats}

out vec4 outColor;

${COMMON_GLSL}

${scene.glsl}

${passes.map((pass) => pass.glsl).join("\n")}

void main() {
  vec2 uv = gl_FragCoord.xy / u_size;
  vec3 lin = scene(uv, u_time);
  /* A night scene on a light page: the light it adds over its own dark
     ground is laid onto the page as a pale tint, its hue washed most of
     the way to white and never more than a light wash, so a horizon reads
     as a soft dawn on paper rather than a dark block on it. */
  if (u_lightMode > 0.5) {
    vec3 light = max(lin - u_ground, vec3(0.0));
    float peak = max(light.r, max(light.g, light.b));
    vec3 hue = light / max(peak, 1e-4);
    vec3 pastel = mix(hue, vec3(1.0), 0.3);
    float strength = clamp(pow(dot(light, vec3(0.2126, 0.7152, 0.0722)) * 4.0, 0.7), 0.0, 0.85);
    lin = mix(u_page, u_page * pastel, strength);
  }
${call("light", "lin")}
  vec3 srgb = pow(max(lin, vec3(0.0)), vec3(1.0 / 2.2));
  /* A one-step dither under everything, so wide ramps never band. */
  srgb += (float(ihash(uvec2(gl_FragCoord.xy)) & 255u) / 255.0 - 0.5) / 255.0;
${call("srgb", "srgb")}
  outColor = vec4(clamp(srgb, 0.0, 1.0), 1.0);
}
`;
}

/**
 * The GLSL every scene and pass can call: ShaderField's integer hash (no
 * fract(sin()) patterning, so no lines in the grain), value noise, fbm and
 * the one-sided Gaussian the horizon is built from.
 */
export const COMMON_GLSL = /* glsl */ `
uint ihash(uvec2 p) {
  p = p * uvec2(73333u, 7777u) ^ (p.yx >> 3u);
  uint h = p.x ^ (p.y * 2654435761u);
  h ^= h >> 15u;
  h *= 2246822519u;
  h ^= h >> 13u;
  return h;
}

float rnd(ivec2 p) {
  return float(ihash(uvec2(p)) >> 8) * (1.0 / 16777216.0);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  ivec2 c = ivec2(i) + 4096;
  return mix(
    mix(rnd(c), rnd(c + ivec2(1, 0)), u.x),
    mix(rnd(c + ivec2(0, 1)), rnd(c + ivec2(1, 1)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * vnoise(p);
    p = p * 2.02 + vec2(17.0, 9.0);
    a *= 0.5;
  }
  return s;
}

/* A one-sided Gaussian: one sigma above zero, another below. */
float lobe(float d, float above, float below) {
  float s = d > 0.0 ? above : below;
  return exp(-(d * d) / (2.0 * s * s));
}
`;

/**
 * The finishing passes, in the order they run. Light passes work on the
 * linear colour and pull it toward the page ground (`u_page`, the page's
 * own colour, which a night scene on a light page does not share with its
 * own `u_ground`); srgb passes work on
 * the encoded colour. Each is compiled into every shader and switched by
 * its `u_<id>_on` uniform, so toggling one never recompiles.
 */
import type { Pass } from "./types";

export const PASSES: Pass[] = [
  {
    id: "scrim",
    label: "Scrim",
    stage: "light",
    on: false,
    params: [{ key: "amount", label: "Amount", min: 0, max: 0.9, step: 0.01, default: 0.35 }],
    glsl: /* glsl */ `
vec3 pass_scrim(vec3 c, vec2 uv) {
  return mix(c, u_page, u_scrim_amount);
}`,
  },
  {
    id: "vignette",
    label: "Vignette",
    stage: "light",
    on: false,
    params: [
      { key: "amount", label: "Amount", min: 0, max: 1, step: 0.01, default: 0.5 },
      { key: "size", label: "Size", min: 0.2, max: 1.2, step: 0.01, default: 0.75 },
    ],
    glsl: /* glsl */ `
vec3 pass_vignette(vec3 c, vec2 uv) {
  vec2 q = (uv - 0.5) * vec2(u_size.x / u_size.y, 1.0);
  float v = smoothstep(u_vignette_size, u_vignette_size * 0.35, length(q));
  return mix(u_page, c, mix(1.0, v, u_vignette_amount));
}`,
  },
  {
    id: "fadeTop",
    label: "Fade the top",
    stage: "light",
    on: true,
    params: [
      { key: "start", label: "Starts at", min: 0.2, max: 0.95, step: 0.01, default: 0.43 },
      { key: "softness", label: "Softness", min: 0.3, max: 2, step: 0.01, default: 0.75 },
    ],
    glsl: /* glsl */ `
vec3 pass_fadeTop(vec3 c, vec2 uv) {
  float f = 1.0 - pow(smoothstep(u_fadeTop_start, 1.0, uv.y), u_fadeTop_softness);
  return mix(u_page, c, f);
}`,
  },
  {
    id: "fadeBottom",
    label: "Fade the bottom",
    stage: "light",
    on: true,
    params: [
      { key: "from", label: "Solid below", min: 0, max: 0.4, step: 0.01, default: 0.04 },
      { key: "to", label: "Clear above", min: 0.05, max: 0.7, step: 0.01, default: 0.3 },
    ],
    glsl: /* glsl */ `
vec3 pass_fadeBottom(vec3 c, vec2 uv) {
  float f = smoothstep(u_fadeBottom_from, max(u_fadeBottom_to, u_fadeBottom_from + 0.01), uv.y);
  return mix(u_page, c, f);
}`,
  },
  {
    id: "grain",
    label: "Film grain",
    stage: "srgb",
    on: true,
    params: [{ key: "amount", label: "Amount", min: 0, max: 0.4, step: 0.005, default: 0.198 }],
    glsl: /* glsl */ `
vec3 pass_grain(vec3 c, vec2 uv) {
  uvec2 gp = uvec2(gl_FragCoord.xy) + uvec2(
    uint(fract(u_time * 7.31) * 1024.0) * 7919u,
    uint(fract(u_time * 3.17) * 1024.0) * 104729u
  );
  float gr = float(ihash(gp) & 255u) / 255.0 - 0.5;
  return c + gr * u_grain_amount * 0.35;
}`,
  },
];

/**
 * The renderer both canvases share: the live stage and the thumbnail baker.
 * `createRenderer` compiles one scene with the passes into a program on a
 * WebGL2 context and returns a `draw` that sets every uniform from a values
 * object and paints one frame. `readColours` resolves a scene's tokens from
 * the live cascade.
 */
import { assemble, uniformNames, VERTEX } from "./assemble";
import type { Pass, Scene, Values } from "./types";
import { MAX_COLOURS } from "./types";

export type Rgb = [number, number, number];

/** A near-black ground in linear RGB, which a night-only scene computes its light against on a light page. */
const NIGHT_GROUND: Rgb = [0.0015, 0.0018, 0.003];
export type Colours = {
  /** The ground the scene is painted against. */
  ground: Rgb;
  /** The page's own ground, which the passes fade to. */
  page: Rgb;
  /** A night scene on a light page, laid on as a pale tint. */
  lightMode: boolean;
  colours: Rgb[];
};

/** Resolves the page ground and a scene's tokens to linear RGB at `host`. */
export function readColours(host: HTMLElement, tokens: string[]): Colours {
  const probe = document.createElement("span");
  probe.style.display = "none";
  host.appendChild(probe);
  const dot = document.createElement("canvas");
  dot.width = 1;
  dot.height = 1;
  const ctx = dot.getContext("2d", { willReadFrequently: true });
  const lin = (c: number) => Math.pow(c / 255, 2.2);
  const read = (token: string): Rgb => {
    if (!ctx) return [0.2, 0.2, 0.2];
    probe.style.color = `var(${token})`;
    ctx.clearRect(0, 0, 1, 1);
    ctx.fillStyle = getComputedStyle(probe).color;
    ctx.fillRect(0, 0, 1, 1);
    const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
    return [lin(r), lin(g), lin(b)];
  };
  const ground = read("--color-bg-page-primary");
  const colours = tokens.slice(0, MAX_COLOURS).map(read);
  probe.remove();
  return { ground, page: ground, lightMode: false, colours };
}

/**
 * A scene's colours for a surface: read from the cascade. A night-only
 * scene on a light page computes its light against a dark ground of its
 * own, and the shader lays that light onto the page as a pale tint
 * (u_lightMode), so its masks still fade to the page and the theme stays
 * light.
 */
export function coloursFor(host: HTMLElement, scene: Scene): Colours {
  const colours = readColours(host, scene.colours);
  const pageIsDark = document.documentElement.getAttribute("data-theme") === "dark";
  if (scene.mode === "dark" && !pageIsDark) {
    colours.ground = NIGHT_GROUND;
    colours.lightMode = true;
  }
  return colours;
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn(gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** The value a uniform takes from a values object. */
function valueOf(values: Values, passes: Pass[], name: string): number {
  for (const pass of passes) {
    const prefix = `u_${pass.id}_`;
    if (!name.startsWith(prefix)) continue;
    const state = values.passes[pass.id];
    const key = name.slice(prefix.length);
    if (key === "on") return state?.on ? 1 : 0;
    return state?.params[key] ?? 0;
  }
  return values.scene[name.slice(2)] ?? 0;
}

export function createRenderer(gl: WebGL2RenderingContext, scene: Scene, passes: Pass[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fs = compile(gl, gl.FRAGMENT_SHADER, assemble(scene, passes));
  const program = gl.createProgram();
  if (!vs || !fs || !program) return null;
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.useProgram(program);
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);

  const at = (name: string) => gl.getUniformLocation(program, name);
  const uSize = at("u_size");
  const uTime = at("u_time");
  const uGround = at("u_ground");
  const uPage = at("u_page");
  const uLightMode = at("u_lightMode");
  const uCols = at("u_col");
  const floats = uniformNames(scene, passes).map((name) => [name, at(name)] as const);

  return {
    setColours({ ground, page, lightMode, colours }: Colours) {
      gl.uniform3fv(uGround, ground);
      gl.uniform3fv(uPage, page);
      gl.uniform1f(uLightMode, lightMode ? 1 : 0);
      const flat = new Float32Array(MAX_COLOURS * 3);
      colours.forEach((rgb, i) => flat.set(rgb, i * 3));
      gl.uniform3fv(uCols, flat);
    },
    draw(values: Values, time: number, width: number, height: number) {
      gl.viewport(0, 0, width, height);
      gl.uniform2f(uSize, width, height);
      gl.uniform1f(uTime, time);
      for (const [name, location] of floats) gl.uniform1f(location, valueOf(values, passes, name));
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteVertexArray(vao);
      gl.deleteProgram(program);
      gl.deleteShader(vs);
      gl.deleteShader(fs);
    },
  };
}

/**
 * Paints each recipe once on a throwaway context and returns the pictures
 * as data URLs, then releases the context, so the tiles cost no live GPU
 * context of their own and the page keeps one.
 */
export function bakeThumbnails(
  host: HTMLElement,
  jobs: { scene: Scene; values: Values }[],
  passes: Pass[],
  width: number,
  height: number
): string[] {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const gl = canvas.getContext("webgl2", { antialias: false, alpha: false, preserveDrawingBuffer: true });
  if (!gl) return jobs.map(() => "");
  const urls = jobs.map(({ scene, values }) => {
    const renderer = createRenderer(gl, scene, passes);
    if (!renderer) return "";
    renderer.setColours(coloursFor(host, scene));
    renderer.draw(values, 20, width, height);
    const url = canvas.toDataURL("image/jpeg", 0.85);
    renderer.dispose();
    return url;
  });
  gl.getExtension("WEBGL_lose_context")?.loseContext();
  return urls;
}

/**
 * ShaderScene's scenes. Each is one look: its GLSL `scene()`, its settings
 * as typed data (so a host can draw a slider per setting) and the colour
 * roles it reads. Both read the background field's roles
 * (`--color-ambient-*`), the ones a theme tunes for ambient shaders, so a
 * theme recolours them with no wiring.
 */
import type { Scene } from './types';

/**
 * The horizon, ported from /labs/horizon as a scene: a planet's limb at
 * night with a fixed sun at the apex, soft layers of light along the arc,
 * a hazy world of land and cloud below, and deep ocean blue further down.
 * The horizon lab's own fades and grain are passes here, so they can be switched
 * and tuned like any other scene's.
 */
export const horizon: Scene = {
  id: "horizon",
  label: "Horizon",
  description: "A planet's limb at night, a fixed sun at the apex, a hazy world and ocean below.",
  mode: "dark",
  /* The background field's roles, the ones a preset tunes for ambient
     shaders and a DESIGN.md import rewrites from the action colour: in the
     base theme they are cobalt, amber, coral and gold, so the horizon's own
     look is unchanged, and an import recolours it with the field. */
  colours: [
    "--color-ambient-4",
    "--color-ambient-6",
    "--color-ambient-5",
    "--color-ambient-1",
  ],
  params: [
    { key: "crown", label: "Horizon height", min: 0.15, max: 0.75, step: 0.01, default: 0.4 },
    { key: "curve", label: "Flatness", min: 1.5, max: 10, step: 0.1, default: 5 },
    { key: "warp", label: "Flow", min: 0, max: 0.2, step: 0.005, default: 0.07 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "clouds", label: "Clouds", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "ocean", label: "Ocean", min: 0, max: 2.5, step: 0.01, default: 1 },
    { key: "beam", label: "Beam", min: 0, max: 2.5, step: 0.01, default: 1 },
  ],
  glsl: /* glsl */ `
#define u_scatter u_col[0]
#define u_halo u_col[1]
#define u_rim u_col[2]
#define u_sun u_col[3]

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y);

  vec2 q = vec2(
    fbm(p * 1.4 + vec2(0.0, t * 0.03)),
    fbm(p * 1.4 + vec2(5.2, 1.3) - t * 0.024)
  );
  vec2 w = p + u_warp * (q - 0.5);

  float crown = u_crown;
  float radius = u_curve * max(aspect, 1.0);
  vec2 centre = vec2(0.0, crown - radius);
  vec2 wl = p + u_warp * 0.17 * (q - 0.5);
  float d = length(wl - centre) - radius;

  float halfW = 0.5 * aspect;
  float sunX = exp(-pow(w.x, 2.0) / (2.0 * 0.28 * 0.28));
  float wide = exp(-pow(w.x, 2.0) / (2.0 * 0.75 * 0.75));
  float energy = (0.4 + 0.45 * wide + 0.9 * sunX) * u_glow;
  float side = clamp(abs(w.x) / halfW, 0.0, 1.0);

  float curtain = fbm(vec2(w.x * 5.0 + t * 0.05, d * 1.2 - t * 0.02));
  float band = fbm(vec2(w.x * 1.2 - t * 0.035, d * 11.0 + t * 0.015));
  float veil = fbm(vec2(w.x * 2.2 + t * 0.02, d * 3.5 - t * 0.01) + q * 1.5);

  vec3 amber = mix(u_halo, u_sun, 0.35);
  vec3 light = vec3(0.0);
  light += u_scatter * lobe(d - 0.02, 0.24, 0.12) * (0.12 + 0.08 * curtain) * (0.7 + 0.5 * energy);
  light += mix(u_scatter, vec3(1.0), 0.35) * lobe(d - 0.05, 0.12, 0.05)
    * (0.06 + 0.16 * smoothstep(0.35, 0.8, curtain)) * energy;
  light += mix(amber, u_rim, side * 0.4) * lobe(d - 0.01, 0.07, 0.045) * (0.35 + 0.35 * band) * energy;
  light += mix(amber, u_sun, 0.3) * lobe(d, 0.02, 0.012) * (0.45 + 0.2 * band) * energy;
  light += mix(amber, vec3(1.0), 0.35) * lobe(d - 0.002, 0.006, 0.003) * 0.55 * energy;
  light += u_rim * lobe(d + 0.03, 0.05, 0.07) * (0.22 + 0.18 * veil) * (0.6 + 0.5 * energy);
  light *= 1.0 - 0.8 * smoothstep(0.0, -0.4, d);

  float below = max(-d, 0.0);
  float onGround = smoothstep(0.002, -0.012, d);
  float z = 1.0 / (below * 2.4 + 0.08);
  vec2 sp = vec2(w.x * z * 0.55, z * 0.5);
  float drift = t * 0.018;

  vec2 lp = sp * 0.9 + vec2(drift * 0.4, drift);
  float land = fbm(lp + 1.4 * vec2(fbm(lp * 0.7 + 3.1), fbm(lp * 0.7 + 8.4)));
  land = smoothstep(0.42, 0.72, land);
  vec2 cp = sp * 1.6 + vec2(-drift * 1.6, drift * 1.3);
  float cloud = fbm(cp + 2.0 * vec2(fbm(cp * 0.5 + q), fbm(cp * 0.5 - q + 5.0)));
  vec2 fp = sp * 3.4 + vec2(-drift * 2.4, drift * 1.8) + q * 0.8;
  float fine = fbm(fp + 1.2 * vec2(fbm(fp * 0.6 + 2.3), fbm(fp * 0.6 + 6.1)));
  cloud = smoothstep(0.42, 0.8, cloud);
  cloud = clamp(cloud + 0.55 * smoothstep(0.5, 0.85, fine), 0.0, 1.0) * u_clouds;
  float streaks = fbm(vec2(sp.x * 0.35 - drift * 2.0, sp.y * 4.0));

  float reach = exp(-below / 0.45);
  float near = exp(-below / 0.07);
  vec3 world = vec3(0.0);
  world += mix(u_ground, u_scatter, 0.5) * land * 0.14 * (0.35 + reach);
  world += mix(u_scatter, vec3(1.0), 0.3) * cloud * 0.48 * reach;
  world += mix(u_rim, amber, 0.4) * cloud * near * 0.6 * energy;
  world += u_scatter * streaks * 0.08 * reach;

  vec2 src = vec2(0.0, crown - 0.005);
  vec2 r = p - src;
  float ang = atan(r.x, -r.y);
  float shafts = smoothstep(0.2, 0.95, fbm(vec2(ang * 1.6, 3.7)));
  float cone = exp(-pow(ang, 2.0) / (2.0 * 0.55 * 0.55));
  float dist = length(r);
  float beams = shafts * cone * exp(-dist / 0.6);
  vec3 beamColour = mix(mix(amber, u_sun, 0.3), u_scatter, smoothstep(0.08, 0.45, dist) * 0.7);
  world += beamColour * beams * 0.45 * (0.65 + 0.5 * cloud) * u_beam;

  float bloomSky = exp(-dot(r, r) / (2.0 * 0.09 * 0.09));
  float bloomWide = exp(-dot(r, r) / (2.0 * 0.28 * 0.28));
  light += mix(u_sun, vec3(1.0), 0.35) * (bloomSky * 0.45 + bloomWide * 0.12) * u_glow;
  world += mix(u_sun, amber, 0.4) * bloomWide * 0.12 * u_glow;

  float sea = smoothstep(0.02, 0.16, below) * (1.0 - 0.65 * land);
  vec3 deep = mix(u_scatter, u_ground, 0.2);
  world *= mix(vec3(1.0), normalize(u_scatter + 0.05) * 1.2, smoothstep(0.08, 0.3, below) * 0.5);
  world += deep * sea * (0.16 + 0.07 * streaks + 0.05 * veil + 0.14 * cloud) * u_ocean;

  light += world * onGround;
  return u_ground + light;
}
`,
};

/**
 * The rift, after /labs/rift, as a soft shader rather than streaming type:
 * a glowing vertical tear in the page that opens widest at its middle and
 * narrows to a seam at either end, a bright core inside a wide glow and a
 * faint haze, and streaks of light drawn in toward it from both sides. The
 * tear's line wanders slowly, and the colour runs from one ambient tone at
 * the top to another at the bottom, the rift lab's own pair.
 */
export const rift: Scene = {
  id: "rift",
  label: "Rift",
  description: "A glowing tear in the page, opening at its middle, light streaming in.",
  mode: "dark",
  colours: ["--color-ambient-2", "--color-ambient-3", "--color-ambient-1"],
  params: [
    { key: "offset", label: "Position", min: -0.45, max: 0.45, step: 0.01, default: 0 },
    { key: "open", label: "Opening", min: 0, max: 1.5, step: 0.01, default: 0.8 },
    { key: "glow", label: "Glow", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "wave", label: "Wander", min: 0, max: 1, step: 0.01, default: 0.4 },
    { key: "streaks", label: "Streaks", min: 0, max: 2, step: 0.01, default: 1 },
    { key: "flow", label: "Flow", min: 0, max: 0.3, step: 0.005, default: 0.08 },
  ],
  glsl: /* glsl */ `
#define u_from u_col[0]
#define u_to u_col[1]
#define u_spark u_col[2]

vec3 scene(vec2 uv, float t) {
  float aspect = u_size.x / u_size.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);

  vec2 q = vec2(
    fbm(p * 1.6 + vec2(0.0, t * 0.03)),
    fbm(p * 1.6 + vec2(5.2, 1.3) - t * 0.025)
  );

  /* The tear's line, wandering slowly along its length. */
  float cx = u_offset * aspect + u_wave * 0.35 * (fbm(vec2(p.y * 1.6, t * 0.04)) - 0.5);
  float dx = p.x - cx + u_flow * (q.x - 0.5);
  float ady = abs(dx);

  /* Widest at the middle, a seam at the ends. */
  float open = u_open * exp(-(p.y * p.y) / (2.0 * 0.3 * 0.3));
  float coreW = 0.006 + 0.01 * open;
  float glowW = 0.07 + 0.2 * open;
  float core = exp(-(dx * dx) / (2.0 * coreW * coreW)) * (0.25 + 0.6 * open);
  float glow = exp(-(dx * dx) / (2.0 * glowW * glowW)) * (0.25 + 0.75 * open);
  float haze = exp(-ady / 0.38) * (0.4 + 0.6 * open);

  /* Streaks drawn in toward the tear: bands that move inward over time. */
  float s = fbm(vec2(ady * 3.0 + t * 0.35, p.y * 42.0 + q.y * 3.0));
  float streak = smoothstep(0.58, 0.86, s) * exp(-ady / 0.2) * smoothstep(0.01, 0.06, ady) * u_streaks;

  vec3 colour = mix(u_from, u_to, smoothstep(-0.45, 0.45, p.y + (q.y - 0.5) * 0.4));
  vec3 light = vec3(0.0);
  light += colour * glow * 0.7 * u_glow;
  light += colour * haze * 0.1;
  light += mix(colour, vec3(1.0), 0.45) * core * 0.7 * u_glow;
  light += mix(colour, u_spark, 0.35) * streak * 0.22;
  return u_ground + light;
}
`,
};

/** Every scene, in picker order. */
export const SCENES = [horizon, rift];

/**
 * The playground's shader vocabulary (the Shaders view, and the ground it
 * lays under every view). A scene is one look (a horizon, a blob field); a pass is a finishing step any scene can take (grain, a fade, a
 * vignette); a recipe is a scene, its settings, and which passes are on
 * with theirs. Every setting is declared as data, so the panel draws its
 * sliders from the declaration and never needs a hand-built control.
 */

/** One numeric setting, drawn as a slider. */
export type ParamSpec = {
  key: string;
  label: string;
  min: number;
  max: number;
  step: number;
  default: number;
};

/**
 * A look. `glsl` defines `vec3 scene(vec2 uv, float t)`, returning the
 * final linear colour of the pixel over the page ground (`u_ground`). Its
 * settings arrive as `uniform float u_<key>`, and its colours as
 * `u_col[i]` in the order `colours` lists their tokens.
 */
export type Scene = {
  id: string;
  label: string;
  description: string;
  /** Colour tokens, resolved from the live cascade into `u_col[0..]`. */
  colours: string[];
  /**
   * `dark` for a scene that only reads on a dark ground (it adds light).
   * On a light page its surface paints a near-black ground of its own
   * (coloursFor), rather than setting data-theme on itself: a nested
   * [data-theme] matches the base dark tokens and would hide the theme
   * preset's colours.
   */
  mode?: "dark";
  params: ParamSpec[];
  glsl: string;
};

/**
 * A finishing step. `glsl` defines one function named `pass_<id>`: a
 * `light` pass takes and returns the linear colour, before encoding; an
 * `srgb` pass takes and returns the encoded colour. Its settings arrive as
 * `uniform float u_<id>_<key>`, and `u_<id>_on` switches it.
 */
export type Pass = {
  id: string;
  label: string;
  stage: "light" | "srgb";
  on: boolean;
  params: ParamSpec[];
  glsl: string;
};

/** What the canvas reads every frame. A ref holds it, so a drag never renders. */
export type Values = {
  speed: number;
  scene: Record<string, number>;
  passes: Record<string, { on: boolean; params: Record<string, number> }>;
};

/** A recipe as it is copied out: the scene's id with the values above. */
export type Recipe = Values & { sceneId: string };

export const MAX_COLOURS = 8;

export function defaultsFor(params: ParamSpec[]) {
  return Object.fromEntries(params.map((param) => [param.key, param.default]));
}
